static char *read_file(const char *path) {
    FILE *f = runtime.fopen(path, "rb");
    if (!f) {
        runtime.fprintf(runtime.stderr, "fakecc: cannot open '%s'\n", path);
        runtime.exit(1);
    }
    runtime.fseek(f, 0, 2);
    long size = runtime.ftell(f);
    runtime.fseek(f, 0, 0);
    char *buf = runtime.malloc((size_t)size + 1);
    if (!buf) {
        runtime.fprintf(runtime.stderr, "fakecc: out of memory\n");
        runtime.exit(1);
    }
    size_t nread = runtime.fread(buf, 1, (size_t)size, f);
    buf[nread] = '\0';
    runtime.fclose(f);
    return buf;
}
static int parse_source(const char *source, const char *filename,
                        TranslationUnit *tu, PkgContext *pkg) {
    TokenArray tokens;
    token_array_init(&tokens);
    if (lex(source, filename, &tokens) != FAKECC_OK) {
        token_array_free(&tokens);
        return FAKECC_ERR;
    }
    tu_init(tu);
    int rc = parse_in_pkg(&tokens, tu, pkg);
    token_array_free(&tokens);
    return rc;
}
static int lower_tu(TranslationUnit *tu, const char *filename,
                    EmitModule *out, int opt_level, int want_debug,
                    PkgContext *pkg) {
    if (sema_check_in_pkg(tu, 0, pkg) != FAKECC_OK)
        return FAKECC_ERR;
    if (sema_has_errors())
        return FAKECC_ERR;
    IRModule ir;
    ir_module_init(&ir);
    if (ir_generate(tu, &ir, opt_level == 0) != FAKECC_OK) {
        ir_module_free(&ir);
        return FAKECC_ERR;
    }
    opt(&ir, opt_level, want_debug);
    emit_module_init(out);
    if (want_debug)
        out->dbg_tu_name = xstrdup(filename);
    codegen(&ir, out, want_debug);
    ir_module_free(&ir);
    return FAKECC_OK;
}
